var _byChar = null

function _index() {
    if (_byChar)
        return _byChar

    _byChar = {}
    for (var i = 0; i < entries.length; i++)
        _byChar[entries[i].ch] = entries[i]

    return _byChar
}

// поиск по имени и ключевым словам внутри группы
// (пустая строка — вся группа)
function search(query, group) {
    const q = query.trim().toLowerCase()
    const res = []

    for (let i = 0; i < entries.length; i++) {
        const e = entries[i]

        if (group && e.group !== group)
            continue
        if (q === "") {
            res.push(e)
            continue
        }
        if (e.name.toLowerCase().indexOf(q) !== -1
                || e.kw.toLowerCase().indexOf(q) !== -1)
            res.push(e)
    }

    return res
}

function infoOf(ch) {
    return _index()[ch]
}

function nameOf(ch) {
    const e = _index()[ch]

    return e ? e.name : ""
}

